using Sunder.Agent.Execution.Common;
using System.Text;
using Sunder.Package.Agent.Contracts.Models;
using Sunder.Package.Agent.Protocol;

namespace Sunder.Package.Agent.Tools.Files;

internal static class FilePatchHandler
{
    public static async Task<AgentToolResult> ExecuteAsync(
        FileExecutionTarget target,
        AgentExecutionTargetContext context,
        AgentToolRequest request,
        CancellationToken cancellationToken)
    {
        if (!FileToolArguments.TryParsePatch(request.ArgumentsJson, out var args, out var error))
        {
            return FileToolResult.Error(request.ToolId, error!, "files-arguments-invalid");
        }

        IReadOnlyList<FilePatchOperation> operations;
        FilePatchPlan plan;
        try
        {
            operations = FilePatchParser.Parse(args.PatchText);
            plan = await FilePatchPlanner.PreflightAsync(target, context, operations, cancellationToken);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            return FileToolResult.Error(request.ToolId, $"Patch preflight failed. No files were changed. {ex.Message}", "patch-preflight-failed");
        }

        try
        {
            return await ApplyPlanAsync(target, context, request.ToolId, operations, plan, cancellationToken);
        }
        finally
        {
            await ReleasePostMutationAuthorityAsync(target, plan).ConfigureAwait(false);
        }
    }

    private static async Task<AgentToolResult> ApplyPlanAsync(
        FileExecutionTarget target,
        AgentExecutionTargetContext context,
        string toolId,
        IReadOnlyList<FilePatchOperation> operations,
        FilePatchPlan plan,
        CancellationToken cancellationToken)
    {
        var applied = new List<PlannedFilePatchOperation>();
        PlannedFilePatchOperation? currentOperation = null;
        try
        {
            foreach (var operation in plan.Operations)
            {
                currentOperation = operation;
                var result = await ApplyOperationAsync(target, context, operation, cancellationToken);
                operation.PostMutationResource = result.PostMutationResource;
                if (result.IsError)
                {
                    return await BuildApplicationFailureAsync(target, context, toolId, plan, applied, operation, result.Summary);
                }

                applied.Add(operation);
            }
        }
        catch (OperationCanceledException)
        {
            var compensation = await CompensateAfterFailureAsync(
                target,
                context,
                applied,
                currentOperation,
                CancellationToken.None,
                requireOriginalStateForNoMutation: true);
            if (CompensationIsConfirmedComplete(compensation))
            {
                throw;
            }

            return BuildCancellationFailure(toolId, plan, applied, currentOperation, compensation);
        }
        catch (Exception ex)
        {
            var failedOperation = plan.Operations[Math.Min(applied.Count, plan.Operations.Count - 1)];
            return await BuildApplicationFailureAsync(target, context, toolId, plan, applied, failedOperation, ex.Message);
        }

        return FileToolResult.Success(
            toolId,
            FilePatchParser.BuildSummary(operations),
            string.Join(Environment.NewLine, plan.Operations.Select(FormatSuccessSummary)), FileToolResult.BackendId(target),
            presentationPayloadJson: FileDiffPresentation.BuildPayload(plan.Operations.Select(operation => operation.PresentationFile).ToArray()));
    }

    private static async ValueTask<AgentFileMutationResult> ApplyOperationAsync(
        FileExecutionTarget target,
        AgentExecutionTargetContext context,
        PlannedFilePatchOperation operation,
        CancellationToken cancellationToken)
    {
        var operationContext = context with
        {
            ApprovedResourceReferences = [operation.ResourceReference],
            ResourceOperation = context.ResourceOperation is { } resourceOperation
                ? resourceOperation with { ResourceIndex = operation.ResourceIndex }
                : null,
            CapturePostMutationResource = true,
        };
        return operation.Kind switch
        {
            FilePatchOperationKind.Add => await FileWriteHandler.WriteAsync(target, operationContext, operation.Path, operation.NextContent!, overwrite: false, cancellationToken),
            FilePatchOperationKind.Update => await FileWriteHandler.WriteAsync(target, operationContext, operation.Path, operation.NextContent!, overwrite: true, cancellationToken, operation.ExpectedContentHash),
            FilePatchOperationKind.Delete => await FileDeleteHandler.DeleteAsync(target, operationContext, operation.Path, cancellationToken, operation.ExpectedContentHash),
            _ => throw new InvalidOperationException($"Unsupported patch operation for {operation.Path}."),
        };
    }

    private static async Task<AgentToolResult> BuildApplicationFailureAsync(
        FileExecutionTarget target,
        AgentExecutionTargetContext context,
        string toolId,
        FilePatchPlan plan,
        IReadOnlyList<PlannedFilePatchOperation> applied,
        PlannedFilePatchOperation failed,
        string failure)
    {
        var compensation = await CompensateAfterFailureAsync(
            target,
            context,
            applied,
            failed,
            CancellationToken.None,
            requireOriginalStateForNoMutation: false);
        if (compensation.AttemptedCount == 0 && compensation.ProbeFailure is null)
        {
            return FileToolResult.Error(
                toolId,
                $"Patch application failed at '{failed.Path}' before any operation completed. Preflight made no changes. {failure}",
                "patch-apply-failed");
        }

        var message = new StringBuilder();
        if (applied.Count == 0)
        {
            message.Append("Patch application failed at '")
                .Append(failed.Path)
                .Append("' before any operation reported completion. ");
        }
        else
        {
            message.Append("Patch was partially applied: ")
                .Append(applied.Count)
                .Append(" of ")
                .Append(plan.Operations.Count)
                .Append(" operations completed before '")
                .Append(failed.Path)
                .Append("' failed. ");
        }
        message.Append(failure.Trim());
        AppendCompensationDiagnostics(message, compensation);

        if (compensation.Result.FullyRestored && compensation.ProbeFailure is null)
        {
            message.Append(" No applied patch changes remain.");
        }
        else
        {
            message.Append(" The target may remain partially modified.");
        }

        return FileToolResult.Error(toolId, message.ToString(), "patch-partial-application");
    }

    private static async Task<FilePatchCompensationAttempt> CompensateAfterFailureAsync(
        FileExecutionTarget target,
        AgentExecutionTargetContext context,
        IReadOnlyList<PlannedFilePatchOperation> applied,
        PlannedFilePatchOperation? failed,
        CancellationToken cancellationToken,
        bool requireOriginalStateForNoMutation)
    {
        IReadOnlyList<PlannedFilePatchOperation> targets = applied;
        FilePatchCompensationProbeFailure? probeFailure = null;
        if (failed is not null && !applied.Contains(failed))
        {
            try
            {
                if (await FailedOperationReachedNextStateAsync(
                        target,
                        context,
                        failed,
                        cancellationToken,
                        requireOriginalStateForNoMutation))
                {
                    targets = [.. applied, failed];
                }
            }
            catch (Exception exception)
            {
                probeFailure = new FilePatchCompensationProbeFailure(failed.Path, exception.Message);
            }
        }

        var result = await CompensateAsync(target, context, targets, cancellationToken);
        return new FilePatchCompensationAttempt(targets.Count, result, probeFailure);
    }

    private static async Task<bool> FailedOperationReachedNextStateAsync(
        FileExecutionTarget target,
        AgentExecutionTargetContext context,
        PlannedFilePatchOperation operation,
        CancellationToken cancellationToken,
        bool requireOriginalStateForNoMutation)
    {
        if (operation.PostMutationResource is { } postMutationResource)
        {
            var reachedNextState = operation.Kind == FilePatchOperationKind.Delete
                ? !postMutationResource.Exists
                : postMutationResource.Exists;
            return !reachedNextState && requireOriginalStateForNoMutation
                ? throw UncertainCanceledOperationState(operation.Path)
                : reachedNextState;
        }

        var resource = await target.Service.ResolveFileAsync(new() { Context = context, Path = operation.Path }, cancellationToken);
        var readContext = context with
        {
            ApprovedResourceReferences = [resource.CanonicalReference],
        };
        if (operation.Kind == FilePatchOperationKind.Delete)
        {
            if (!resource.Exists)
            {
                return true;
            }
            if (!requireOriginalStateForNoMutation)
            {
                return false;
            }

            var current = await ReadCurrentContentAsync(
                target,
                readContext,
                operation.Path,
                cancellationToken,
                requireCompleteRead: true);
            if (string.Equals(current, operation.OriginalContent, StringComparison.Ordinal))
            {
                return false;
            }
            return requireOriginalStateForNoMutation
                ? throw UncertainCanceledOperationState(operation.Path)
                : false;
        }

        if (!resource.Exists)
        {
            if (operation.Kind == FilePatchOperationKind.Add)
            {
                return false;
            }
            return requireOriginalStateForNoMutation
                ? throw UncertainCanceledOperationState(operation.Path)
                : false;
        }

        var currentContent = await ReadCurrentContentAsync(
            target,
            readContext,
            operation.Path,
            cancellationToken,
            requireCompleteRead: requireOriginalStateForNoMutation);
        if (string.Equals(currentContent, operation.NextContent, StringComparison.Ordinal))
        {
            return true;
        }
        if (operation.Kind == FilePatchOperationKind.Update
            && string.Equals(currentContent, operation.OriginalContent, StringComparison.Ordinal))
        {
            return false;
        }
        return requireOriginalStateForNoMutation
            ? throw UncertainCanceledOperationState(operation.Path)
            : false;
    }

    private static async Task<FilePatchCompensationResult> CompensateAsync(
        FileExecutionTarget target,
        AgentExecutionTargetContext context,
        IReadOnlyList<PlannedFilePatchOperation> applied,
        CancellationToken cancellationToken)
    {
        var restored = new List<string>();
        var failures = new List<FilePatchCompensationFailure>();
        foreach (var operation in applied.Reverse())
        {
            try
            {
                var result = await CompensateOperationAsync(target, context, operation, cancellationToken);
                if (result.IsError)
                {
                    failures.Add(new FilePatchCompensationFailure(operation.Path, result.Summary));
                }
                else
                {
                    restored.Add(operation.Path);
                }
            }
            catch (Exception ex)
            {
                failures.Add(new FilePatchCompensationFailure(operation.Path, ex.Message));
            }
        }

        return new FilePatchCompensationResult(restored, failures);
    }

    private static async Task<AgentFileMutationResult> CompensateOperationAsync(
        FileExecutionTarget target,
        AgentExecutionTargetContext context,
        PlannedFilePatchOperation operation,
        CancellationToken cancellationToken)
    {
        var resource = operation.PostMutationResource
                       ?? await target.Service.ResolveFileAsync(new() { Context = context, Path = operation.Path }, cancellationToken);
        var operationContext = CreateCompensationContext(context, operation, resource);
        switch (operation.Kind)
        {
            case FilePatchOperationKind.Add:
                return await FileDeleteHandler.DeleteAsync(
                    target,
                    operationContext,
                    operation.Path,
                    cancellationToken,
                    FileOperation.ComputeContentHash(operation.NextContent!));

            case FilePatchOperationKind.Update:
                return await FileWriteHandler.WriteAsync(
                    target,
                    operationContext,
                    operation.Path,
                    operation.OriginalContent!,
                    overwrite: true,
                    cancellationToken,
                    FileOperation.ComputeContentHash(operation.NextContent!));

            case FilePatchOperationKind.Delete:
                return await FileWriteHandler.WriteAsync(target, operationContext, operation.Path, operation.OriginalContent!, overwrite: false, cancellationToken);

            default:
                return UnsafeCompensation(operation.Path);
        }
    }

    private static AgentExecutionTargetContext CreateCompensationContext(
        AgentExecutionTargetContext context,
        PlannedFilePatchOperation operation,
        AgentResolvedResource resource)
    {
        var deleteCompensation = operation.Kind == FilePatchOperationKind.Add;
        var resourceReference = deleteCompensation
            ? resource.DeleteCanonicalReference ?? resource.CanonicalReference
            : resource.CanonicalReference;
        var resourceClaim = deleteCompensation
            ? resource.DeleteResourceClaim ?? resource.ResourceClaim
            : resource.ResourceClaim;
        var capabilities = deleteCompensation
            ? resource.DeleteAuthorityReferences.Concat(resource.AuthorityReferences)
            : resource.AuthorityReferences;
        return context with
        {
            ApprovedResourceReferences = [resourceReference],
            ApprovedResourceClaims = resourceClaim is null ? [] : [resourceClaim],
            ApprovedResourceCapabilities = capabilities.Distinct(StringComparer.Ordinal).ToArray(),
            ResourceOperation = context.ResourceOperation is { } resourceOperation
                ? resourceOperation with { ResourceIndex = operation.ResourceIndex }
                : null,
            CapturePostMutationResource = false,
        };
    }

    private static async ValueTask ReleasePostMutationAuthorityAsync(
        FileExecutionTarget target,
        FilePatchPlan plan)
    {
        if (!FilesExecutionFacets.SupportsFacet(target, AgentExecutionFacetIds.ResourceAuthority))
        {
            return;
        }

        var capabilities = plan.Operations
            .Select(static operation => operation.PostMutationResource)
            .Where(static resource => resource is not null)
            .SelectMany(static resource => resource!.AuthorityReferences.Concat(resource.DeleteAuthorityReferences))
            .Where(static capability => !string.IsNullOrWhiteSpace(capability))
            .Distinct(StringComparer.Ordinal)
            .ToArray();
        if (capabilities.Length > 0)
        {
            await target.Service.ReleaseResourceAuthorityAsync(capabilities, CancellationToken.None).ConfigureAwait(false);
        }
    }

    private static async Task<string?> ReadCurrentContentAsync(
        FileExecutionTarget target,
        AgentExecutionTargetContext context,
        string path,
        CancellationToken cancellationToken,
        bool requireCompleteRead)
    {
        var current = await target.Service.ReadFileAsync(new() { Context = context, Request = new() { Path = path, Offset = null, Limit = null } }, cancellationToken);
        if (current.IsError || current.IsDirectory || current.WasTruncated)
        {
            if (!requireCompleteRead)
            {
                return null;
            }
            throw new InvalidOperationException(
                $"The current state of '{path}' could not be verified after the interrupted mutation. "
                + (current.ErrorMessage ?? "A complete regular-file read was unavailable."));
        }
        return current.Content;
    }

    private static InvalidOperationException UncertainCanceledOperationState(string path)
        => new($"The current state of '{path}' matches neither the preflight state nor the planned patch state.");

    private static AgentFileMutationResult UnsafeCompensation(string path)
        => new() { Path = path, Summary = "Current target state no longer matches the applied patch; automatic compensation was skipped.",
            IsError = true, ErrorCode = "patch-compensation-unsafe", PostMutationResource = null };

    private static AgentToolResult BuildCancellationFailure(
        string toolId,
        FilePatchPlan plan,
        IReadOnlyList<PlannedFilePatchOperation> applied,
        PlannedFilePatchOperation? currentOperation,
        FilePatchCompensationAttempt compensation)
    {
        var message = new StringBuilder()
            .Append("Patch execution was canceled after ")
            .Append(applied.Count)
            .Append(" of ")
            .Append(plan.Operations.Count)
            .Append(" operations reported completion");
        if (currentOperation is not null)
        {
            message.Append(" while applying '")
                .Append(currentOperation.Path)
                .Append('\'');
        }
        message.Append('.');
        AppendCompensationDiagnostics(message, compensation);
        message.Append(" The target may remain partially modified.");
        return FileToolResult.Error(toolId, message.ToString(), "patch-partial-application");
    }

    private static bool CompensationIsConfirmedComplete(FilePatchCompensationAttempt compensation)
        => compensation.ProbeFailure is null
           && compensation.Result.FullyRestored
           && compensation.Result.RestoredCount == compensation.AttemptedCount;

    private static void AppendCompensationDiagnostics(
        StringBuilder message,
        FilePatchCompensationAttempt compensation)
    {
        message.AppendLine()
            .Append("Compensation restored ")
            .Append(FileToolResult.FormatCount(compensation.Result.RestoredCount, "operation"))
            .Append(". Completed rollbacks: ")
            .Append(FormatRollbackPaths(compensation.Result.RestoredPaths))
            .Append(". Failed rollbacks: ")
            .Append(compensation.Result.Failures.Count == 0
                ? "none"
                : string.Join(
                    "; ",
                    compensation.Result.Failures.Select(static failure => $"'{failure.Path}': {failure.Failure}")))
            .Append('.');
        if (compensation.ProbeFailure is { } probeFailure)
        {
            message.Append(" The operation '")
                .Append(probeFailure.Path)
                .Append("' could not be verified for compensation because diagnostic probing was unavailable: ")
                .Append(probeFailure.Failure)
                .Append('.');
        }
    }

    private static string FormatRollbackPaths(IReadOnlyList<string> paths)
        => paths.Count == 0
            ? "none"
            : string.Join(", ", paths.Select(static path => $"'{path}'"));

    private sealed record FilePatchCompensationAttempt(
        int AttemptedCount,
        FilePatchCompensationResult Result,
        FilePatchCompensationProbeFailure? ProbeFailure);

    private static string FormatSuccessSummary(PlannedFilePatchOperation operation)
        => operation.Kind switch
        {
            FilePatchOperationKind.Add => $"Added {operation.Path}",
            FilePatchOperationKind.Update => $"Updated {operation.Path}",
            FilePatchOperationKind.Delete => $"Deleted {operation.Path}",
            _ => operation.Path,
        };
}

using Sunder.Agent.Execution.Common;
using Sunder.Generated.Packages.Sunder_Package_Agent_Services;
using Sunder.Package.Agent.Contracts.Models;
using Sunder.Package.Agent.Protocol;
using Sunder.Sdk.Abstractions;
using Sunder.Sdk.Rpc;
using Sunder.Sdk.Services;
using Sunder.Sdk.Worker;

namespace Sunder.Package.Agent.Tools.Files;

[SunderServiceProvider(typeof(IToolSourceService), ProviderId = "files.tools")]
[SunderServiceProvider(typeof(IPermissionSurfaceService), ProviderId = "files.permissions")]
[SunderServiceProvider(typeof(IPromptContextContributorService), ProviderId = "files.prompt.context")]
[SunderServiceProvider(typeof(ISessionCleanerService), ProviderId = "files.session.cleaner")]
public sealed partial class FilesToolSource : IToolSourceService, IPermissionSurfaceService, IPromptContextContributorService, ISessionCleanerService, ISunderWorkerActivationService
{
    private const int MaxPostAccessScopePaths = 64;
    private readonly Lazy<ScopedInstructionContextService> _scopedInstructions;

    /// <summary>Creates a Files source with required scoped-instruction persistence and enforcement.</summary>
    public FilesToolSource(IPackageContext packageContext)
    {
        ArgumentNullException.ThrowIfNull(packageContext);
        _scopedInstructions = new Lazy<ScopedInstructionContextService>(
            () => new ScopedInstructionContextService(packageContext),
            LazyThreadSafetyMode.ExecutionAndPublication);
    }

    public ValueTask ActivateAsync(SunderWorkerContext context, CancellationToken token = default)
    { token.ThrowIfCancellationRequested(); _ = ScopedInstructions; return ValueTask.CompletedTask; }

    public string SourceId => FileToolDescriptorRegistry.SourceId;

    public string DisplayName => FileToolDescriptorRegistry.DisplayName;

    public string SourceKind => "workspace";

    public string SurfaceId => "files";

    public string ContributorId => FileToolDescriptorRegistry.SourceId;

    public string CleanerId => "agent.files.scoped-instruction-claims";

    public string AcknowledgmentSinkId => "agent.files.scoped-instruction-acknowledgment";

    public ValueTask<AgentToolSourceDescriptor> DescribeAsync(CancellationToken token = default)
    { token.ThrowIfCancellationRequested(); return ValueTask.FromResult(new AgentToolSourceDescriptor { SourceId = SourceId, DisplayName = DisplayName, SourceKind = SourceKind }); }

    ValueTask<AgentPermissionSurfaceDescriptor> IPermissionSurfaceService.DescribeAsync(CancellationToken token)
    { token.ThrowIfCancellationRequested(); return ValueTask.FromResult(new AgentPermissionSurfaceDescriptor { SurfaceId = SurfaceId, DisplayName = DisplayName, Actions = ListActions() }); }

    ValueTask<AgentPromptContextContributorDescriptor> IPromptContextContributorService.DescribeAsync(CancellationToken token)
    { token.ThrowIfCancellationRequested(); return ValueTask.FromResult(new AgentPromptContextContributorDescriptor { ContributorId = ContributorId, DisplayName = DisplayName, AcknowledgmentSinkId = AcknowledgmentSinkId }); }

    ValueTask<AgentServiceIdentity> ISessionCleanerService.DescribeAsync(CancellationToken token)
    { token.ThrowIfCancellationRequested(); return ValueTask.FromResult(new AgentServiceIdentity { Id = CleanerId, DisplayName = CleanerId }); }

    public ValueTask<AgentToolPresentation?> PresentationAsync(AgentToolPresentationRequest request, CancellationToken token = default)
    { token.ThrowIfCancellationRequested(); return ValueTask.FromResult(FileToolPresentationAdapter.Resolve(request)); }

    public ValueTask<IReadOnlyList<AgentToolDescriptor>> ListToolsAsync(
        AgentToolSourceContext context,
        CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        return ValueTask.FromResult(FileToolDescriptorRegistry.Descriptors);
    }

    public async ValueTask<AgentToolReadiness?> GetReadinessAsync(
        CSunder_Agent_Tool_Source_ToolSourceGetReadinessRequest request,
        CancellationToken cancellationToken = default)
    {
        var (toolId, context) = (request.ToolId, request.Context);
        if (!FileToolDescriptorRegistry.Contains(toolId))
        {
            return null;
        }

        if (context.Workspace is null)
        {
            return new() { ToolId = toolId, Status = AgentToolReadinessStatus.Failed, Message = "File tools require a selected workspace." };
        }

        if (context.ExecutionBinding is null)
        {
            return new() { ToolId = toolId, Status = AgentToolReadinessStatus.Failed, Message = "The selected workspace is not bound to an installed execution target." };
        }
        var targetLease = await AcquireTargetAsync(
                context.ExecutionTarget,
                context.ExecutionBinding,
                cancellationToken)
            .ConfigureAwait(false);
        if (targetLease is null)
        {
            return new() { ToolId = toolId, Status = AgentToolReadinessStatus.Failed, Message = "The selected workspace is not bound to an installed execution target." };
        }

        return await InvokeTargetAsync(
            targetLease,
            cancellationToken,
            async (target, invocationToken) =>
            {
                if ((toolId.Equals("grep", StringComparison.OrdinalIgnoreCase)
                     || toolId.Equals("glob", StringComparison.OrdinalIgnoreCase))
                    && !FilesExecutionFacets.SupportsFacet(target, AgentExecutionFacetIds.StructuredFileSearch))
                {
                    return new AgentToolReadiness { ToolId = toolId, Status = AgentToolReadinessStatus.Failed,
                        Message = "The selected target does not support governed structured file search." };
                }

                if (!FilesExecutionFacets.SupportsFacet(target, AgentExecutionFacetIds.ScopedInstructionDiscovery)
                    || !FilesExecutionFacets.SupportsFacet(target, AgentExecutionFacetIds.ExecutionScope))
                {
                    return new AgentToolReadiness { ToolId = toolId, Status = AgentToolReadinessStatus.Failed,
                        Message = "The selected target does not support scoped-instruction discovery required by first-party Files enforcement." };
                }

                var readiness = await target.Service.ReadinessAsync(
                    FileExecutionTarget.Context(context.SessionId, context.Profile?.ProfileId, context.Workspace, context.ExecutionBinding) with
                    {
                        ExpectedConfigurationGeneration = context.ExecutionTargetConfigurationGeneration,
                    },
                    invocationToken);
                var ready = readiness.Status == AgentExecutionTargetReadinessStatus.Ready && target.Descriptor.SupportsFiles;
                return new AgentToolReadiness { ToolId = toolId, Status = ready ? AgentToolReadinessStatus.Ready : AgentToolReadinessStatus.Failed,
                    Message = ready ? "Workspace file tools are ready with scoped AGENTS.md enforcement." : readiness.Message };
            },
            () => new AgentToolReadiness { ToolId = toolId, Status = AgentToolReadinessStatus.Failed,
                Message = "The selected execution target became unavailable while readiness was being checked." });
    }

    public async ValueTask<AgentToolResult> ExecuteAsync(
        CSunder_Agent_Tool_Source_ToolSourceExecuteRequest invocation,
        CancellationToken cancellationToken = default)
    {
        var (context, request) = (invocation.Context, invocation.Request);
        if (context.Workspace is null)
        {
            return FileToolResult.Error(request.ToolId, "File tools require a selected workspace.", "files-workspace-required");
        }

        if (context.ExecutionBinding is null)
        {
            return FileToolResult.Error(request.ToolId, "The selected workspace is not bound to an installed execution target.", "files-target-required");
        }
        var targetLease = await AcquireTargetAsync(
                context.ExecutionTarget,
                context.ExecutionBinding,
                cancellationToken)
            .ConfigureAwait(false);
        if (targetLease is null)
        {
            return FileToolResult.Error(request.ToolId, "The selected workspace is not bound to an installed execution target.", "files-target-required");
        }

        return await InvokeTargetAsync(
            targetLease,
            cancellationToken,
            async (target, invocationToken) =>
            {
                var targetContext = FileExecutionTarget.Context(context.SessionId, context.ProfileId, context.Workspace, context.ExecutionBinding) with
                {
                    AllowOutsideConfiguredScope = context.AllowOutsideConfiguredScope,
                    ApprovedResourceReferences = context.ApprovedResourceReferences,
                    ApprovedResourceClaims = context.ApprovedResourceClaims,
                    ApprovedResourceCapabilities = context.ApprovedResourceCapabilities,
                    ResourceOperation = context.ResourceOperation,
                    ExpectedConfigurationGeneration = context.ExecutionTargetConfigurationGeneration,
                };
                try
                {
                    if (IsMutation(request.ToolId)
                        && await PreflightAsync(new() { Context = context, Request = request }, invocationToken) is { } deferred)
                    {
                        return deferred;
                    }

                    AgentToolResult result;
                    IReadOnlyList<AgentScopedInstructionProbe> accessProbes = [];
                    if (request.ToolId.Equals("read", StringComparison.OrdinalIgnoreCase))
                    {
                        var readResult = await FileReadHandler.ExecuteAsync(target, targetContext, request, invocationToken);
                        result = readResult.Result;
                        if (!result.IsError
                            && FileToolArguments.TryParseRead(request.ArgumentsJson, out var read, out _))
                        {
                            accessProbes = [new() { Path = read.Path, IsDirectory = readResult.IsDirectory, FollowFinalSymbolicLink = true }];
                        }
                    }
                    else
                    {
                        switch (request.ToolId.ToLowerInvariant())
                        {
                            case "write":
                                result = await FileWriteHandler.ExecuteWriteAsync(target, targetContext, request, invocationToken);
                                break;
                            case "edit":
                                result = await FileWriteHandler.ExecuteEditAsync(target, targetContext, request, invocationToken);
                                break;
                            case "apply_patch":
                                result = await FilePatchHandler.ExecuteAsync(target, targetContext, request, invocationToken);
                                break;
                            case "grep":
                                {
                                    var search = await FileSearchHandler.ExecuteGrepAsync(target, targetContext, request, invocationToken);
                                    result = search.Result;
                                    accessProbes = search.MatchedPaths
                                        .Select(path => new AgentScopedInstructionProbe { Path = path, IsDirectory = false, FollowFinalSymbolicLink = true })
                                        .ToArray();
                                    break;
                                }
                            case "glob":
                                {
                                    var search = await FileSearchHandler.ExecuteGlobAsync(target, targetContext, request, invocationToken);
                                    result = search.Result;
                                    accessProbes = search.MatchedPaths
                                        .Select(path => new AgentScopedInstructionProbe { Path = path, IsDirectory = false, FollowFinalSymbolicLink = true })
                                        .ToArray();
                                    break;
                                }
                            default:
                                result = FileToolResult.Error(request.ToolId, $"Unknown file tool '{request.ToolId}'.", "files-tool-unknown");
                                break;
                        }
                    }
                    if (IsMutation(request.ToolId))
                    {
                        return result with { RequiresPromptContextRefresh = true };
                    }

                    if (!result.IsError && accessProbes.Count > 0)
                    {
                        if (accessProbes.Count > MaxPostAccessScopePaths)
                        {
                            return WithheldAccessResult(
                                target,
                                request.ToolId,
                                $"The result referenced more than {MaxPostAccessScopePaths} distinct paths. Narrow the read or search and rerun it.",
                                "files-scoped-instruction-result-path-limit",
                                requiresRefresh: false);
                        }
                        try
                        {
                            var claim = await ScopedInstructions.ClaimAfterAccessAsync(
                                target,
                                context,
                                accessProbes,
                                invocationToken);
                            if (claim == ScopedInstructionAccessClaimResult.RefreshRequired)
                            {
                                return WithheldAccessResult(
                                    target,
                                    request.ToolId,
                                    "Applicable AGENTS.md instructions were discovered or changed. Prompt context must refresh before this result is requested again.",
                                    "files-prompt-context-refresh-required",
                                    requiresRefresh: true);
                            }
                        }
                        catch (OperationCanceledException)
                        {
                            throw;
                        }
                        catch (SunderRpcException)
                        {
                            throw;
                        }
                        catch (Exception ex)
                        {
                            return WithheldAccessResult(
                                target,
                                request.ToolId,
                                $"Scoped instruction discovery failed after access. The successful result was withheld. {BoundMessage(ex.Message)}",
                                "files-scoped-instruction-discovery-failed",
                                requiresRefresh: true);
                        }
                    }

                    return result;
                }
                catch (Exception ex) when (ex is not OperationCanceledException and not SunderRpcException)
                {
                    return FileToolResult.Error(request.ToolId, ex.Message, "files-execution");
                }
                finally
                {
                    if (FilesExecutionFacets.SupportsFacet(target, AgentExecutionFacetIds.ResourceAuthority))
                    {
                        await target.Service.ReleaseResourceAuthorityAsync(targetContext.ApprovedResourceCapabilities, CancellationToken.None).ConfigureAwait(false);
                    }
                }
            },
            () => FileToolResult.Error(
                request.ToolId,
                "The selected execution target became unavailable while the file operation was running.",
                AgentToolResultErrorCodes.PackageUnavailable));
    }

    public async ValueTask<AgentPermissionRequest?> PermissionAsync(
        CSunder_Agent_Tool_Source_ToolSourcePermissionRequest invocation,
        CancellationToken cancellationToken = default)
    {
        var (context, request) = (invocation.Context, invocation.Request);
        if (context.ExecutionBinding is null)
        {
            return await FilePermissionPlanner.BuildAsync(null, context, request, cancellationToken);
        }
        var targetLease = await AcquireTargetAsync(
                context.ExecutionTarget,
                context.ExecutionBinding,
                cancellationToken)
            .ConfigureAwait(false);
        if (targetLease is null)
        {
            return await FilePermissionPlanner.BuildAsync(null, context, request, cancellationToken);
        }

        return await InvokeTargetAsync(
            targetLease,
            cancellationToken,
            (target, invocationToken) => FilePermissionPlanner.BuildAsync(target, context, request, invocationToken),
            static () => null);
    }

